/* Named workspaces live on the service. Only the private access key is device-local. */
(function(){
'use strict';
const API='https://nova-hive-viewer.georgiadis-c.chatgpt.site',B=globalThis.HiveArchiveBridge,I=globalThis.HiveI18n,t=(k,p)=>I.t(k,p),$=id=>document.getElementById(id),KEY='nova-hive-archive-key-v1';
let selected=null,items=[],busy=false,key=null;
const status=(k,p)=>{$('archive-status').textContent=t(k,p);};
function getKey(){if(key)return key;key=localStorage.getItem(KEY);if(!/^[a-f0-9]{64}$/.test(key??'')){key=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');localStorage.setItem(KEY,key);}return key;}
async function request(path,method='GET',body){let r;try{r=await fetch(API+'/api/plans'+path,{method,headers:{Authorization:'Bearer '+getKey(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(45000)});}catch{throw Error(t('Kartenarchiv nicht erreichbar. Dein aktueller Plan bleibt erhalten.'));}const v=await r.json();if(!r.ok)throw Error(t(v.error??'Kartenarchiv nicht erreichbar. Dein aktueller Plan bleibt erhalten.'));return v;}
async function run(fn){if(busy)return;busy=true;for(const id of ['archive-save','archive-copy','archive-viewer','archive-refresh','archive-key-load'])$(id).disabled=true;try{await fn();}catch(e){status(e.message);B.toast(e.message);}finally{busy=false;for(const id of ['archive-save','archive-copy','archive-viewer','archive-refresh','archive-key-load'])$(id).disabled=false;}}
function shareLink(id){return 'https://sunnyharry.github.io/Nova-Hive-Planer/viewer/?plan='+encodeURIComponent(id);}
function showLink(id){$('archive-link').value=shareLink(id);$('archive-share').hidden=false;}
function draw(){const list=$('archive-list');list.replaceChildren();if(!items.length){const p=document.createElement('p');p.className='field-help';p.textContent=t('Noch keine gespeicherten Karten.');list.append(p);return;}for(const item of items){const card=document.createElement('article');card.className='archive-card'+(selected?.id===item.id?' active':'');const title=document.createElement('strong');title.textContent=item.name;const meta=document.createElement('small');meta.textContent=new Date(item.updatedAt).toLocaleString(I.language)+(item.shared?' · Viewer':'');const actions=document.createElement('div');for(const [label,action] of [['Laden',()=>load(item)],['Viewer',()=>viewSaved(item)],['Löschen',()=>remove(item)]]){const b=document.createElement('button');b.textContent=t(label);if(label==='Löschen')b.className='danger';b.addEventListener('click',action);actions.append(b);}card.append(title,meta,actions);list.append(card);}}
async function refresh(){const data=await request('');items=data.plans.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));draw();}
function load(item){B.confirm(()=>run(async()=>{const record=await request('/'+item.id);B.load(record.workspace);selected=record;$('archive-name').value=record.name;$('archive-share').hidden=!record.shared;if(record.shared)showLink(record.id);draw();status('Karte geladen.');}));}
function remove(item){if(busy)return;B.requestConfirm(t('Karte löschen?'),t('Die gespeicherte Karte und ihr Viewer-Link werden entfernt. Der geöffnete Plan bleibt erhalten.'),()=>run(async()=>{await request('/'+item.id,'DELETE',{version:item.version});if(selected?.id===item.id){selected=null;$('archive-share').hidden=true;}await refresh();status('Karte gelöscht.');}));}
const sameWorkspace=(a,b)=>{const clean=v=>{const q={...v};delete q.savedAt;return JSON.stringify(q);};return clean(a)===clean(b);};
async function save(copy=false,publish=false){const name=$('archive-name').value.trim();if(!name){$('archive-name').focus();throw Error(t('Bitte einen Kartennamen eingeben.'));}const id=copy||!selected?crypto.randomUUID():selected.id,snapshot=B.getWorkspace(),record=await request('/'+id,'PUT',{name,workspace:snapshot,version:copy||!selected?0:selected.version,share:publish||(!copy&&!!selected?.shared)});selected=record;if(sameWorkspace(snapshot,B.getWorkspace()))B.markSaved();if(record.shared)showLink(id);else $('archive-share').hidden=true;await refresh();status('Karte gespeichert.');return id;}
function viewerTab(){const tab=window.open('about:blank','_blank');if(tab){tab.opener=null;tab.document.title='Nova Hive Viewer';tab.document.body.textContent=t('Viewer wird vorbereitet …');}return tab;}
function viewSaved(item){if(busy)return;const tab=viewerTab();run(async()=>{try{if(!item.shared){const record=await request('/'+item.id);const saved=await request('/'+item.id,'PUT',{name:record.name,workspace:record.workspace,version:record.version,share:true});if(selected?.id===item.id)selected=saved;await refresh();}showLink(item.id);if(tab)tab.location.replace(shareLink(item.id));status('Viewer-Link bereit. Jeder mit diesem Link kann die Karte sehen.');}catch(e){tab?.close();throw e;}});}
$('archive-save').addEventListener('click',()=>run(()=>save()));$('archive-copy').addEventListener('click',()=>run(()=>save(true)));
$('archive-viewer').addEventListener('click',()=>{if(busy)return;if(!$('archive-name').value.trim()){status('Bitte einen Kartennamen eingeben.');$('archive-name').focus();return;}const tab=viewerTab();run(async()=>{try{const id=await save(false,true);if(tab)tab.location.replace(shareLink(id));status('Viewer-Link bereit. Jeder mit diesem Link kann die Karte sehen.');}catch(e){tab?.close();throw e;}});});
$('archive-link-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('archive-link').value);status('Link kopiert.');}catch{$('archive-link').select();status('Link markieren und kopieren.');}});
$('archive-refresh').addEventListener('click',()=>run(refresh));
$('archive-key-save').addEventListener('click',()=>run(async()=>{const blob=new Blob([JSON.stringify({schema:'nova-hive-archive-access',key:getKey()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nova-hive-archiv-schluessel.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));
$('archive-key-load').addEventListener('click',()=>$('archive-key-file').click());
$('archive-key-file').addEventListener('change',e=>run(async()=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;if(f.size>1000)throw Error(t('Ungültige Archiv-Schlüsseldatei.'));const data=JSON.parse(await f.text());if(data.schema!=='nova-hive-archive-access'||!/^[a-f0-9]{64}$/.test(data.key))throw Error(t('Ungültige Archiv-Schlüsseldatei.'));B.requestConfirm(t('Archiv wechseln?'),t('Sichere zuerst deinen bisherigen Archiv-Schlüssel. Der geöffnete Plan bleibt erhalten.'),()=>run(async()=>{localStorage.setItem(KEY,data.key);key=data.key;selected=null;$('archive-share').hidden=true;await refresh();}));}));
$('language-select').addEventListener('change',()=>{draw();status('Online gespeicherte Karten. Eine Karte enthält alle 21 Varianten.');});
run(async()=>{await refresh();status('Online gespeicherte Karten. Eine Karte enthält alle 21 Varianten.');});
})();
